WITH flattened AS (SELECT id, customer_id, created_at, coupon_codes, attr_key, v FROM carts LATERAL VIEW OUTER EXPLODE(attributes) t AS attr_key, v), exploded AS (SELECT id, customer_id, code FROM flattened LATERAL VIEW OUTER EXPLODE(coupon_codes) e AS code), filtered AS (SELECT *, UPPER(code) AS code_upper FROM exploded WHERE code IS NOT NULL) SELECT code, COUNT(DISTINCT customer_id) AS distinct_customer_ids, COUNT(*) AS cnt, COUNT(*) AS event_count, COUNT(*) AS num_rows, COUNT(*) FILTER (WHERE code = 'BUNDLE') AS bundle_rows, COUNT(DISTINCT customer_id) AS distinct_customer_ids_2 FROM filtered GROUP BY code HAVING bundle_rows > 1;
